<body class="bg-body-tertiary"><?php $this->load->view('components/top_nav.php'); ?><main class="container py-4 py-lg-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1">Users</h1><p class="text-secondary mb-0">Manage registered application accounts separately from employees.</p></div><a class="btn btn-primary" href="<?= html_escape(site_url('register')); ?>">Register user</a></div><section class="card border-0 shadow-sm rounded-4 overflow-hidden"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Name</th><th>Email</th><th>Birthday</th><th>Address</th><th>Registered</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td class="fw-semibold"><?= html_escape($user['firstname'] . ' ' . $user['lastname']); ?></td><td><?= html_escape($user['email']); ?></td><td><?= html_escape($user['birthday']); ?></td><td><?= html_escape($user['address']); ?></td><td><?= html_escape($user['created_at']); ?></td><td class="text-end"><?php if ((int) $user['Id'] !== (int) $current_user['id']): ?><?= form_open('users/delete/' . (int) $user['Id'], array('class' => 'd-inline', 'onsubmit' => "return confirm('Delete this user?');")); ?><button class="btn btn-sm btn-outline-danger" type="submit">Delete</button><?= form_close(); ?><?php else: ?><span class="text-secondary small">Current account</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></main><?php $this->load->view('components/modals/alert.php'); ?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="<?= html_escape(base_url('assets/js/app.js')); ?>"></script></body></html>
